          const response = await fetch(`/api/projects/${encodeURIComponent(id)}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }) });
          if (!response.ok) return showProject(id, (await response.json()).error, selectedFilter, selectedPriority);
          showProject(id, '', selectedFilter, selectedPriority);
        });
        const filter = app.querySelector('#task-filter');
        const priorityFilter = app.querySelector('#priority-filter');
        const applyFilters = () => app.querySelectorAll('.task-row').forEach(row => {
          const completionMatches = filter.value === 'All' || (filter.value === 'Open' ? row.dataset.completed !== 'true' : row.dataset.completed === 'true');
          row.hidden = !completionMatches || (priorityFilter.value !== 'All' && priorityFilter.value !== row.dataset.priority);
        });
        applyFilters();
        filter.addEventListener('change', applyFilters);
        priorityFilter.addEventListener('change', applyFilters);
        app.querySelector('#task-form').addEventListener('submit', async event => {
          event.preventDefault();
          const title = new FormData(event.currentTarget).get('title').trim();
          if (!title) return showProject(id, 'Task title is required');
          const created = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }) });
          if (!created.ok) return showProject(id, (await created.json()).error, filter.value, priorityFilter.value);
          showProject(id, '', filter.value, priorityFilter.value);
        });
        app.querySelectorAll('input[type="checkbox"][data-task-id]').forEach(checkbox => checkbox.addEventListener('change', async () => {
          await fetch(`/api/tasks/${checkbox.dataset.taskId}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
          showProject(id, '', filter.value);
        }));
        app.querySelectorAll('[data-priority-task-id]').forEach(select => select.addEventListener('change', async () => {
          const response = await fetch(`/api/tasks/${select.dataset.priorityTaskId}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ priority: select.value }) });
          if (!response.ok) showProject(id, '', filter.value);
        }));
        app.querySelectorAll('.task-rename-form').forEach(form => form.addEventListener('submit', async event => {
          event.preventDefault();
          const title = new FormData(form).get('title').trim();
          if (!title) return showProject(id, 'Task title is required', filter.value);
          const response = await fetch(`/api/tasks/${form.dataset.taskId}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }) });
          if (!response.ok) return showProject(id, (await response.json()).error, filter.value);
          showProject(id, '', filter.value);
        }));
      }
